def declared_region():
    return publication.stock_module().Region(key=KEY,rom='JK08A',source=SOURCE,harness=HARNESS,
        start=0x4eba2,end=0x4ebe2,boundary=False,cases=14132,
        pools=((0x8d92,1),(0x91da,8),(0x129c0,6),(0x4ec08,4),(0x4ec20,4),
               (0x4ed60,8),(0x4ed70,20),(0x5b884,4)),
        ram_literals=(0x4ec08,0x4ec20,0x4ed70),
        callees=((0x4ec24,0x4ecac),(0x5b7ec,0x5b884),(0x224f8,0x22508)),
        symbols=(('INHIBIT','fuel_inhibit_mask/ram'),('COMPENSATED','injection_0/ram'),
            ('TRANSFORMED','handsome-spaniel/ram'),('OPENING','portable-kingfisher/ram'),
            ('ADDITIVE','berserk-ocelot/ram'),('SUBTRACTIVE','apricot-raven/ram'),
            ('MULTIPLIER','over_run_channel_multiplier/tbl')),
        constants=(('EARLY_ONLY',0),))

def region_contract(module):
    matches=[row for row in module.REGIONS if row.key==KEY]
    assert len(matches)==1
    [region]=matches
    assert region==declared_region() and type(region.cases) is int
    return region

def stock_contract(data):
    assert sum(len(span) for _,span in SLICES)==423
    for at,span in SLICES:assert data[at:at+len(span)]==span,f'{at:08x}'
    region=declared_region()
    assert sum((end-start)//2 for start,end in region.code_spans)==184
    instructions={at:sh2.decode(int.from_bytes(data[at:at+2],'big'),at)
                  for start,end in region.code_spans for at in range(start,end,2)}
    for at,instruction in instructions.items():
        if instruction.flow=='branch':assert instruction.target in instructions
        if instruction.delayed:assert at+2 in instructions
    assert [int.from_bytes(data[at:at+2],'big') for at in range(0x224f8,0x22508,2)]==[
        0x4021,0x4021,0x4021,0x4021,0x4021,0x4021,0x000b,0x4021]
    assert [int.from_bytes(data[at:at+4],'big') for at in (0x4ed7c,0x4ed80)]==[0x224f8,0x5b7ec]
    assert instructions[0x4ec6c].flow==instructions[0x4ec88].flow=='call'
    assert instructions[0x4eca8].flow==instructions[0x5b880].flow=='return'
    assert bytes(data[0x91da:0x91e2])==bytes.fromhex('35584000109a0000')
    assert data[0x129c0:0x129c6]==bytes([128])*6 and data[0x8d92]==0x7a

@cache
def literals():
    text=(TOOL_DIR/HEADER).read_text()
    [body]=re.findall(r'channel_pulse_cases\[\] = \{(.*?)\n\};',text,re.S)
    body=re.sub(r'(0x[0-9a-f]+|\d+)U\b',r'\1',body)
    rows=ast.literal_eval('['+body.replace('{','[').replace('}',']')+']')
    assert re.findall(r'^#define CHANNEL_PULSE_CASE_COUNT (\d+)U$',text,re.M)==['14132']
    assert len(rows)==14132 and all(len(row)==26 and len(row[24])==len(row[25])==15 for row in rows)
    return rows

@cache
def expressions(formula):
    assert Grammar(repo.config()).validate(formula) is None
    result=[]
    for assignment in formula.split(';'):
        name,expression=assignment.split('=',1)
        expression=re.sub(r'\b([0-9a-f]{8})\b',r'0x\1',expression.strip())
        expression=re.sub(r'\bfrom\b','source',expression)
        result.append((name.strip(),builtins.compile(expression,'channel-arithmetic','eval')))
    return result

def evaluate(formula,env):
    for name,expression in expressions(formula):env[name]=eval(expression,{'__builtins__':{}},env)
    return env

def vector_contract(row):
    (i,argument,mask,even,odd,add,sub,flag,mult,opening,a,c,b,d,variant,t,
     inhibited,h,transformed,exit_t,product,lower,upper,q2,incoming,expected)=row
    assert all(type(value) is int for value in row[:24])
    assert 0<=i<6 and argument&255==i and 0<=argument<=0xffffffff
    assert all(0<=value<=255 for value in (mask,flag,mult))
    assert all(0<=value<=65535 for value in (even,odd,add,sub,opening,a,c,b,d))
    assert variant in (0,1) and t in (0,1) and inhibited==int(bool(mask&(1<<i)))
    signed=lambda value:value if value<32768 else value-65536
    env=dict(x=argument,source=h,RAM8={0xffff22e0:mask},
        RAM16={0xffff191c:even,0xffff191e:odd,0xffff1396+2*i:add,
               0xffff1466+2*i:sub,0xffff2436:opening},
        ROM8={0x8d92:flag,0x129c0+i:mult},ROM16={0x91da:a,0x91dc:c,0x91de:b,0x91e0:d},
        uint8=lambda value:int(value)&255,uint16=lambda value:int(value)&65535,
        uint32=lambda value:int(value)&0xffffffff,int16=signed,min=min,max=max,floor=floor)
    calculation=evaluate(COMPENSATED_FORMULA,env)
    assert calculation['I']==i and calculation['to']==h
    arithmetic=evaluate(TRANSFORMED_FORMULA,env)
    assert arithmetic['to']==transformed
    initial=[((0x81234567+n*0x1020305) if variant else (0x1728394a+n*0x110203))&0xffffffff for n in range(15)]
    initial[4],initial[7]=argument,0x4eba2
    result=initial.copy()
    if inhibited:
        assert transformed==h==opening and exit_t==0 and (lower,upper,q2)==(0,0,0)
        result[4],result[5]=i,mask
    else:
        assert lower==arithmetic['L'] and upper==arithmetic['U']
        assert q2==((c*h+100*d)&0xffffffff)//16384
        result[1],result[3],result[4],result[5]=upper,100,lower,0x010023d4
        result[7]=max(h,lower)
        assert exit_t==int(result[7]>=upper)
    raw=(odd if i&1 else even)+signed(add)-(signed(sub) if flag&8 else 0)
    assert product==(raw*mult if raw>0 else 0)
    result[0],result[2],result[6]=2*i,0x010023c8,h
    assert incoming==initial and expected==result

def chain_contract(model):
    chain=model.entities[('chain','fuel_pulse')]
    assert len(chain.steps)==26
    for number,formula,via,sign in ((20,COMPENSATED_FORMULA,[BUILDER],'positive'),
        (21,COMPENSATED_FORMULA,[BUILDER],'positive'),
        (22,TRANSFORMED_FORMULA,[BUILDER,AFFINE],'none'),
        (23,'to = uint16(from)',['coherent_snapshot/fn','mahogany-bobcat/fn'],'positive')):
        step=publication.normalized(model,chain.steps[number-1])
        assert step['note']==formula and step['via']==via and step['sign']==sign
        assert step['specs']==[SPEC] and Grammar(repo.config()).validate(step['note']) is None
        triples={20:('enlightened-mastodon/ram','injection_0/ram','scales'),
            21:('over_run_channel_multiplier/tbl','injection_0/ram','multiplies'),
            22:('injection_0/ram','handsome-spaniel/ram','limits'),
            23:('handsome-spaniel/ram','berserk-terrier/ram','copies')}
        assert (step['from'],step['to'],step['effect'])==triples[number]

def owner_contract(model):
    for ref,document in OWNER_CONTRACTS.items():
        symbol=document['symbol']
        owner=publication.required_owner(model,ref,int(symbol['address'],16))
        publication.required_properties(model,owner.props,document['props'])
        current=owner.symbols['7mfk']
        for note in symbol['notes']:assert note in current.props.get('note',[])
        publication.required_properties(model,current.props,symbol['props'])
        publication.required_evidence(model,current.evidence,symbol['evidence'])
        for wanted in document['links']:
            matches=[link for link in owner.links if link.type==wanted['type'] and link.to.key==wanted['to']
                     and link.slot==wanted.get('slot') and link.offset==wanted.get('offset')]
            assert len(matches)==1
            [link]=matches
            assert link.stated>=set(wanted['layouts'])
            publication.required_properties(model,link.props,wanted['props'])
            publication.required_evidence(model,link.evidence,wanted['evidence'])
    chain_contract(model)

def snapshot_word_contract(model):
    snapshot.region_contract(publication.stock_module())
    source=publication.required_owner(model,'handsome-spaniel/ram',0xffff23d4).symbols['7mfk']
    target=publication.required_owner(model,'berserk-terrier/ram',0xffff2348).symbols['7mfk']
    assert source.value('width')==target.value('width')==16
    assert source.value('signed') is target.value('signed') is False
    assert source.address-0xffff23bc==target.address-0xffff2330==24
    assert all(24+2*i+1<140 for i in range(6))
    caller=[row for row in snapshot.literals() if row[0]==0x21314]
    assert len(caller)==1316
    affine=caller[:1024]
    for offset in range(24,36):
        assert {(row[6]+29*offset)%256 for row in affine}==set(range(256))
    for row in caller:assert row[1:4]==[0xffff23bc,0xffff2330,140]
    harness=(TOOL_DIR/snapshot.HARNESS).read_text()
    assert 'for (i = 0; i < 65536U; ++i)' in harness
    assert 'ram_before[(test->source & 65535U) + i - destination]' in harness

def publication_contract(text):
    region=region_contract(publication.stock_module())
    counts=(sum((end-start)//2 for start,end in region.code_spans),
            sum(end-start for start,end in region.code_spans)+sum(size for _,size in region.pools),len(literals()))
    for pattern,value in zip((r'\b(\d+) instructions\b',r'\b(\d+) bound bytes\b',r'\b(\d+) literal cases\b'),counts):
        claims=re.findall(pattern,text)
        assert claims and set(map(int,claims))=={value}
    for phrase in ('EARLY_ONLY=0','all fifteen GPRs','actual complete SR','76-byte','96 frame bytes',
        '64k RAM','all 55 bound pool/calibration bytes','000224f8','0005b7ec','140-byte',
        'steps 20, 21, 22 and 23','hardware atomicity','sign = "none"'):
        assert phrase in text

def test_channel_pulse_registered_stock_contract(jk08a_stock_bytes):
    module=publication.stock_module()
    region=region_contract(module)
    stock_contract(jk08a_stock_bytes)
    fixture=module.build_fixture(region,jk08a_stock_bytes)
    expected=bytearray(jk08a_stock_bytes)
    for at in region.ram_literals:expected[at:at+4]=(0x01000000+(int.from_bytes(expected[at:at+4],'big')&65535)).to_bytes(4,'big')
    assert fixture==expected and not region.boundary and not region.ram_word_literals
    for path,digest in EXECUTION_SOURCES.items():assert hashlib.sha256((TOOL_DIR/path).read_bytes()).hexdigest()==digest,path

def test_channel_pulse_chain_owner_contract():
    model=compile.cached(repo.ROOT)
    owner_contract(model)
    snapshot_word_contract(model)

def test_channel_pulse_every_literal_matches_independent_arithmetic_and_complete_state():
    rows=literals()
    for row in rows:vector_contract(row)
    assert {row[0] for row in rows}==set(range(6))
    assert {row[2] for row in rows}=={row[7] for row in rows}=={row[8] for row in rows}==set(range(256))
    assert {tuple(row[10:14]) for row in rows}>={(13656,16384,4250,0),(65535,65535,65535,65535)}
    assert {row[16] for row in rows}=={0,1} and {row[19] for row in rows}=={0,1}
    wrap=[row for row in rows if not row[16] and tuple(row[10:14])==(65535,65535,65535,65535)]
    assert {(row[17],row[18]) for row in wrap}>={(32768,65535),(65534,65534)}

def test_channel_pulse_each_bound_byte_mutation_is_rejected(jk08a_stock_bytes):
    for at,span in SLICES:
        for offset in range(len(span)):
            changed=bytearray(jk08a_stock_bytes);changed[at+offset]^=1
            with pytest.raises(AssertionError):stock_contract(changed)

@pytest.mark.parametrize('register',range(15))
def test_channel_pulse_each_expected_register_mutation_is_rejected(register):
    for index in (0,1,2,3,6,11):
        row=copy.deepcopy(literals()[index]);row[25][register]^=1
        with pytest.raises(AssertionError):vector_contract(row)

@pytest.mark.parametrize('scalar',(0,1,2,5,6,7,8,10,11,12,13,16,17,18,19,20,21,22,23))
def test_channel_pulse_scalar_mutation_is_rejected(scalar):
    row=copy.deepcopy(literals()[2])
    row[scalar]^=(1<<row[0]) if scalar==2 else 8 if scalar==7 else 16384 if scalar in (10,11,12,13) else 1
    with pytest.raises(AssertionError):vector_contract(row)

def test_channel_pulse_all_accepted_region_fields_and_fixtures_remain_exact():
    from dataclasses import asdict
    module=publication.stock_module()
    regions={row.key:row for row in module.REGIONS if row.key!=KEY}
    assert set(regions)==set(HELD_REGIONS)==set(HELD_FIXTURES) and len(regions)==49
    images={rom:module.stock_image(rom) for rom in {row.rom for row in regions.values()}}
    for key,region in regions.items():
        assert asdict(region)==HELD_REGIONS[key]
        assert hashlib.sha256(module.build_fixture(region,images[region.rom])).hexdigest()==HELD_FIXTURES[key]

@pytest.mark.parametrize('field,value',(('cases',0),('boundary',True),('ram_literals',()),
    ('callees',()),('symbols',()),('constants',()),('ram_word_literals',((0x4ed60,0xffff84ec,0x7f00,1),))))
def test_channel_pulse_region_mutation_is_rejected(field,value):
    region=replace(declared_region(),**{field:value})
    with pytest.raises(AssertionError):region_contract(SimpleNamespace(REGIONS=(region,)))

def test_channel_pulse_publication_counts_come_from_registered_sources():
    for path in (SPEC,'tools/sh-elf-run/README.md'):
        text=(repo.ROOT/path).read_text()
        assert text.count('## '+SECTION+'\n')==1
        section=text.split('## '+SECTION+'\n',1)[1].split('\n## ',1)[0]
        publication_contract(section)
        for count,noun in ((185,'instructions'),(424,'bound bytes'),(14133,'literal cases')):
            with pytest.raises(AssertionError):publication_contract(section+f' {count} {noun}')
